// Restore DSP state from PostgreSQL into GLOBAL context (both stores are
// global-scoped: link-producing flows and the health endpoint live on other
// tabs, and Node-RED flow-context is tab-local).
// One-time migration: if a table is empty and the legacy JSON file exists,
// import it, then continue serving from Postgres.
// ponytail: one pg.Client per operation — state writes are <= a few per
// minute; switch to a pooled client only if that ever changes.
const DDL = [
    `CREATE TABLE IF NOT EXISTS dsp_transfers (
        id TEXT PRIMARY KEY,
        state TEXT NOT NULL DEFAULT '',
        doc JSONB NOT NULL,
        updated_at TIMESTAMPTZ NOT NULL DEFAULT now())`,
    `CREATE TABLE IF NOT EXISTS dsp_negotiations (
        id TEXT PRIMARY KEY,
        state TEXT NOT NULL DEFAULT '',
        doc JSONB NOT NULL,
        updated_at TIMESTAMPTZ NOT NULL DEFAULT now())`
];

const LEGACY = {
    dsp_transfers: '/data/dsp-state/transfers.json',
    dsp_negotiations: '/data/dsp-state/negotiations.json'
};

(async () => {
    const client = new pg.Client({ connectionString: env.get('DSP_PG_URI') });
    await client.connect();
    try {
        for (const ddl of DDL) await client.query(ddl);

        const maps = {};
        for (const [table, legacyPath] of Object.entries(LEGACY)) {
            const count = await client.query(`SELECT count(*)::int AS n FROM ${table}`);
            if (count.rows[0].n === 0) {
                let legacy = {};
                try { legacy = JSON.parse(fs.readFileSync(legacyPath, 'utf8')); } catch (e) { /* no legacy file */ }
                for (const [id, doc] of Object.entries(legacy)) {
                    await client.query(
                        `INSERT INTO ${table} (id, state, doc) VALUES ($1, $2, $3) ON CONFLICT (id) DO NOTHING`,
                        [id, (doc && doc.state) || '', doc]);
                }
                if (Object.keys(legacy).length) {
                    node.log('DSP state: migrated ' + Object.keys(legacy).length + ' row(s) from ' + legacyPath);
                }
            }
            const res = await client.query(`SELECT id, doc FROM ${table}`);
            const map = {};
            res.rows.forEach((r) => { map[r.id] = r.doc; });
            maps[table] = map;
        }
        global.set('transfers', maps.dsp_transfers);
        global.set('negotiations', maps.dsp_negotiations);
        node.log('DSP state: ' + Object.keys(maps.dsp_transfers).length + ' transfer(s), '
            + Object.keys(maps.dsp_negotiations).length + ' negotiation(s) restored from PostgreSQL');
    } finally {
        await client.end();
    }
})().catch((err) => {
    // Surfaces on the tab's catch node, which rate-limits a retry — covers
    // Postgres still booting when this instance starts.
    node.error('DSP state restore failed: ' + (err && err.message ? err.message : err), msg);
});
return null;

// Snapshot semantics preserved from the file-based store: re-read the
// authoritative in-memory map and replace the table contents atomically.
// ponytail: one pg.Client per operation — state writes are <= a few per
// minute; switch to a pooled client only if that ever changes.
(async () => {
    const transfers = global.get('transfers') || {};
    const client = new pg.Client({ connectionString: env.get('DSP_PG_URI') });
    await client.connect();
    try {
        await client.query('BEGIN');
        await client.query('DELETE FROM dsp_transfers');
        for (const [id, doc] of Object.entries(transfers)) {
            await client.query(
                'INSERT INTO dsp_transfers (id, state, doc) VALUES ($1, $2, $3)',
                [id, (doc && doc.state) || '', doc]);
        }
        await client.query('COMMIT');
    } catch (err) {
        try { await client.query('ROLLBACK'); } catch (e) { /* connection gone */ }
        throw err;
    } finally {
        await client.end();
    }
})().catch((err) => {
    node.error('DSP state persist (transfers) failed: ' + (err && err.message ? err.message : err), msg);
});
return null;

